1	const crossSpawn = require('cross-spawn');
2	const { parseClaudeUsageOutput } = require('./claude_usage_parsing');
3	const { createUtilityProcessTerminalPoll } = require('./claude_usage_terminal_host');
4	
5	const CLAUDE_USAGE_POLL_COOLDOWN_MS = 120_000;
6	const CLAUDE_USAGE_MAX_OUTPUT_CHARS = 1_000_000;
7	const CLAUDE_USAGE_TERMINAL_TIMEOUT_MS = 20_000;
8	
9	function collectProcessOutput(child, dependencies) {
10	    const { clearTimeout: clearPollTimeout, setTimeout: setPollTimeout, timeoutMs } = dependencies;
11	
12	    return new Promise((resolve, reject) => {
13	        let stdout = '';
14	        let settled = false;
15	        let timeout;
16	        const finish = (result, error = null) => {
17	            if (settled) return;
18	            settled = true;
19	            clearPollTimeout(timeout);
20	            if (error) reject(error);
21	            else resolve(result);
22	        };
23	        // Pipe errors (EPIPE when Claude exits before reading stdin) reach no listener otherwise,
24	        // and an unhandled stream error takes the Electron main process down.
25	        const ignoreStreamError = () => {};
26	        child.stdin?.on('error', ignoreStreamError);
27	        child.stdout?.on('error', ignoreStreamError);
28	        child.stderr?.on('error', ignoreStreamError);
29	        child.stdout?.on('data', (chunk) => {
30	            if (stdout.length >= CLAUDE_USAGE_MAX_OUTPUT_CHARS) return;
31	            stdout += chunk.toString();
32	        });
33	        child.stderr?.resume(); // Unread stderr fills its pipe buffer and blocks Claude forever.
34	        child.on('error', (error) => finish(null, error));
35	        child.on('close', (exitCode) => finish({ exitCode: exitCode ?? 1, stdout }));
36	        timeout = setPollTimeout(() => {
37	            try {
38	                child.kill();
39	            } catch {
40	                // The child is already gone.
41	            }
42	            finish({ exitCode: 1, stdout });
43	        }, timeoutMs);
44	        child.stdin?.end('/usage\n');
45	    });
46	}
47	
48	/**
49	 * Runs Claude `/usage` after Claude output, with a two-minute maximum frequency.
50	 *
51	 * The plain-stdout attempt runs here; the pty fallback runs in a worker process, because node-pty
52	 * cannot be hosted in the main process without risking a native crash that ends the application.
53	 */
54	class ClaudeUsagePoller {
55	    constructor(dependencies = {}) {
56	        this.clearTimeout = dependencies.clearTimeout ?? clearTimeout;
57	        this.cooldownMs = dependencies.cooldownMs ?? CLAUDE_USAGE_POLL_COOLDOWN_MS;
58	        this.cwd = dependencies.cwd ?? process.cwd();
59	        this.env = dependencies.env ?? process.env;
60	        this.executableResolver = dependencies.executableResolver;
61	        this.now = dependencies.now ?? Date.now;
62	        this.onRuntimeEvent = dependencies.onRuntimeEvent;
63	        this.setTimeout = dependencies.setTimeout ?? setTimeout;
64	        this.spawn = dependencies.spawn ?? crossSpawn;
65	        this.terminalPoll = dependencies.terminalPoll ?? createUtilityProcessTerminalPoll();
66	        this.terminalTimeoutMs = dependencies.terminalTimeoutMs ?? CLAUDE_USAGE_TERMINAL_TIMEOUT_MS;
67	        this.processTimeoutMs = dependencies.processTimeoutMs ?? this.terminalTimeoutMs;
68	        this.abortTerminalPoll = null;
69	        this.activePoll = null;
70	        this.lastPollStartedAt = Number.NEGATIVE_INFINITY;
71	        this.pending = false;
72	        this.pendingTimer = null;
73	        this.stopped = false;
74	        if (!this.executableResolver) throw new Error('Claude usage poller requires an executable resolver');
75	        if (typeof this.onRuntimeEvent !== 'function') throw new Error('Claude usage poller requires a runtime event listener');
76	    }
77	
78	    requestPoll({ cwd, env } = {}) {
79	        if (this.stopped) return;
80	        if (cwd) this.cwd = cwd;
81	        if (env) this.env = env;
82	        this.pending = true;
83	        this.schedulePendingPoll();
84	    }
85	
86	    stop() {
87	        this.stopped = true;
88	        this.pending = false;
89	        if (this.pendingTimer) this.clearTimeout(this.pendingTimer);
90	        this.pendingTimer = null;
91	        // A worker left running past shutdown holds a pty open while Electron is already exiting.
92	        this.abortTerminalPoll?.();
93	        this.abortTerminalPoll = null;
94	    }
95	
96	    schedulePendingPoll() {
97	        if (this.stopped || !this.pending || this.activePoll || this.pendingTimer) return;
98	        const delay = Math.max(0, this.cooldownMs - (this.now() - this.lastPollStartedAt));
99	        if (delay === 0) {
100	            this.pending = false;
101	            this.activePoll = this.runPendingPoll();
102	            return;
103	        }
104	        this.pendingTimer = this.setTimeout(() => {
105	            this.pendingTimer = null;
106	            this.schedulePendingPoll();
107	        }, delay);
108	    }
109	
110	    async runPendingPoll() {
111	        try {
112	            await this.poll();
113	        } catch {
114	            // A failing poll must never escape as an unhandled rejection; the next one retries.
115	        }
116	        this.activePoll = null;
117	        this.schedulePendingPoll();
118	    }
119	
120	    async poll() {
121	        this.lastPollStartedAt = this.now();
122	        const observedAt = this.now();
123	        let payload = null;
124	        try {
125	            const executable = await this.executableResolver.find('claude', { cwd: this.cwd, env: this.env }) ?? 'claude';
126	            const child = this.spawn(executable, [], { cwd: this.cwd, env: this.env, stdio: ['pipe', 'pipe', 'pipe'] });
127	            const { exitCode, stdout } = await collectProcessOutput(child, {
128	                clearTimeout: this.clearTimeout,
129	                setTimeout: this.setTimeout,
130	                timeoutMs: this.processTimeoutMs,
131	            });
132	            payload = exitCode === 0 ? parseClaudeUsageOutput(stdout, observedAt) : null;
133	            if (this.stopped) return;
134	            if (!payload) {
135	                const fallback = await this.pollTerminal(executable, observedAt);
136	                if (fallback.unavailable) throw new Error('Claude usage terminal failed');
137	                payload = fallback.payload;
138	            }
139	        } catch {
140	            await this.onRuntimeEvent({ kind: 'unavailable', observedAt: this.now() });
141	
142	            return;
143	        }
144	        if (payload) await this.onRuntimeEvent({ kind: 'snapshot', observedAt, payload });
145	    }
146	
147	    /** Hands the pty attempt to a worker process, which reports usage, unavailability, or neither. */
148	    pollTerminal(executable, observedAt) {
149	        const request = {
150	            cwd: this.cwd,
151	            env: { ...this.env },
152	            executable,
153	            observedAt,
154	            timeoutMs: this.terminalTimeoutMs,
155	        };
156	
157	        return this.terminalPoll(request, {
158	            registerAbort: (abort) => {
159	                this.abortTerminalPoll = abort;
160	            },
161	        });
162	    }
163	}
164	
165	module.exports = { CLAUDE_USAGE_POLL_COOLDOWN_MS, ClaudeUsagePoller };
